'use strict';
const {T,createWorld,blocked,move,portalAt}=World, worlds=createWorld(),KEY='mosswild-save-v1';
const defaults={coins:80,berries:5,wood:0,fish:0,crystals:0,xp:0,team:['Pip'],jobs:{Pip:'berries'},bank:{berries:0,wood:0,fish:0,crystals:0},last:Date.now(),met:false,caught:false,quest:0,upgrade:1,cooldowns:{}};
let state=typeof SaveStore!=='undefined'?(SaveStore.read()||{...defaults}):{...defaults};if(typeof SaveStore==='undefined'){try{state={...defaults,...JSON.parse(localStorage.getItem(KEY)||'{}')};}catch{}}state.cooldowns??={};
const rates={berries:20,wood:30,fish:40,crystals:60},names={berries:'Forage berries',wood:'Gather wood',fish:'Catch fish',crystals:'Find crystals'};
const colors={Pip:'#a4d56b',Emberkin:'#e69758',Dewdrop:'#78cccf',Lunamoth:'#b9a3de'};
let map=worlds.valley,player={x:6*T+16,y:11*T+16,dir:3,walk:0},follower={x:player.x-24,y:player.y+15},keys={},stick={x:0,y:0},sprint=false,dialog=false,transitioning=false,near=null,encounter=null,clockTime=0,padPressed=false,padNav=0,padBack=false,toastTimer;
if(typeof ExpansionWorld!=='undefined')ExpansionWorld.apply(worlds,state.exploration||{});
if(state.position&&worlds[state.position.area]){map=worlds[state.position.area];if(!blocked(map,state.position.x,state.position.y)){player.x=state.position.x;player.y=state.position.y;follower={x:player.x-15,y:player.y+15};}}
function accrue(now=Date.now()){if(typeof FrontierCore!=='undefined')return FrontierCore.idle(state,now,rates);let dt=Math.max(0,Math.min(now-state.last,8*3600000));for(const n of state.team){const job=state.jobs[n];if(rates[job])state.bank[job]=(state.bank[job]||0)+dt/1000/rates[job]*state.upgrade;}state.last=now;return dt;}
const away=accrue();function save(){state.position={area:map.id,x:player.x,y:player.y};if(typeof SaveStore!=='undefined')SaveStore.write(state);else try{localStorage.setItem(KEY,JSON.stringify(state))}catch{}}
const app=document.getElementById('app');app.innerHTML=`<canvas id="world" tabindex="0" aria-label="Mosswild game world. Move with WASD, arrow keys, a gamepad or the on-screen joystick. E or action button interacts."></canvas><div class="hud"><div class="place wood"><strong id="place"></strong><small>☀ Spring, day <span id="day">1</span> · Mosswild</small></div><div class="hud-right"><span class="wood" id="coins"></span><button class="wood" data-ui="bag">Bag / Camp</button><button class="wood" data-ui="help" aria-label="Controls and help">?</button></div></div><div class="quest"><small>YOUR ADVENTURE</small><span id="quest"></span></div><canvas id="minimap" class="minimap" width="108" height="84" aria-label="Area minimap; white dot is your position"></canvas><span class="pad-status" id="pad"></span><div class="controls"><div class="joystick" id="joystick" role="group" aria-label="Drag to move"><div class="knob" id="knob"></div></div><button class="sprint" id="run">Run</button><button class="action" id="action" aria-label="Interact with nearby object" disabled>Action<small>E / A</small></button><span class="near" id="near">Walk up to a person or object</span></div><div class="hint">WASD / arrows to move · E to interact · Shift to run</div><div class="transition" id="fade"></div><div class="area-title" id="area-title"></div>`;
const canvas=document.getElementById('world'),ctx=canvas.getContext('2d'),mini=document.getElementById('minimap').getContext('2d');let W=640,H=400,camera={x:0,y:0};
function resize(){const scale=innerWidth<650?1.35:1.8;W=Math.round(canvas.clientWidth/scale);H=Math.round(canvas.clientHeight/scale);canvas.width=W;canvas.height=H;ctx.imageSmoothingEnabled=false;}addEventListener('resize',resize);resize();
const rr=(x,y,w,h,c)=>{ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),w,h)};
function text(t,x,y,color='#fff4c4',size=9){ctx.font=`bold ${size}px monospace`;ctx.textAlign='center';ctx.fillStyle='#233b2c';ctx.fillText(t,Math.round(x)+1,Math.round(y)+1);ctx.fillStyle=color;ctx.fillText(t,Math.round(x),Math.round(y));}
function tree(x,y,grove=false){rr(x-17,y-7,36,14,'#274f343d');rr(x-4,y-23,9,27,'#78533b');rr(x-2,y-22,3,24,'#a47c4e');rr(x-22,y-39,44,25,grove?'#254a45':'#2c633b');rr(x-17,y-53,34,35,grove?'#326659':'#397944');rr(x-11,y-61,23,39,grove?'#438575':'#50964d');rr(x-15,y-47,10,14,grove?'#538f76':'#65a859');rr(x+8,y-38,10,12,'#316840');rr(x-18,y-22,36,5,'#2a5a37');rr(x-5,y-58,9,3,'#91b86a');}
function human(x,y,mara=false,dir=0,walk=0){let step=Math.sin(walk)*2;rr(x-8,y-3,17,6,'#263e3444');rr(x-6,y-10+step,5,11,'#443b42');rr(x+2,y-10-step,5,11,'#443b42');rr(x-7,y-20,15,12,mara?'#b0768e':'#537f88');rr(x-9,y-18-step,3,8,'#e3b786');rr(x+8,y-18+step,3,8,'#e3b786');rr(x-6,y-30,13,12,'#e2b580');rr(x-7,y-34,15,7,mara?'#dccead':'#75503c');if(!mara){rr(x-10,y-35,21,4,'#d9ba68');rr(x-6,y-40,13,6,'#e4c776');rr(x-6,y-35,13,2,'#98784c');rr(x-4,y-20,8,3,'#d89764');}if(dir!==3){rr(x+(dir===1?-4:dir===2?4:-3),y-25,2,2,'#3e4042');if(dir===0)rr(x+4,y-25,2,2,'#3e4042');}else rr(x-6,y-29,13,7,mara?'#d7caaa':'#79503c');}
function creature(x,y,name,walk=0){const c=colors[name],bob=Math.sin(walk)*1.3;rr(x-9,y-1,19,5,'#1e403f33');y+=bob;rr(x-7,y-13,15,13,'#33503a');rr(x-9,y-11,19,9,c);rr(x-7,y-17,15,15,c);rr(x-8,y-23,5,9,name==='Pip'?'#528a45':c);rr(x+4,y-23,5,9,c);rr(x-5,y-12,2,3,'#293e36');rr(x+5,y-12,2,3,'#293e36');rr(x-5,y-12,1,1,'#fff6d5');rr(x+5,y-12,1,1,'#fff6d5');rr(x,y-7,2,1,'#40563a');rr(x-6,y-1,4,3,'#dec787');rr(x+4,y-1,4,3,'#dec787');if(name==='Pip'){rr(x-1,y-25,3,9,'#608a3d');rr(x+2,y-26,6,4,'#b6d56c');}if(name==='Lunamoth'){rr(x-15,y-18,7,14,'#d8c9ea');rr(x+9,y-18,7,14,'#d8c9ea');rr(x-13,y-16,3,4,'#a49ccf');}}
function house(o){let x=o.x-16,y=o.y-16,w=o.w*T,h=o.h*T;rr(x-4,y+h-7,w+8,16,'#30432b44');rr(x,y+36,w,h-36,'#bd9a62');for(let j=50;j<h;j+=15){rr(x,y+j,w,2,'#a38253');rr(x+7,y+j-9,2,8,'#c9a972');}rr(x+5,y+40,5,h-40,'#785a3c');rr(x+w-10,y+40,5,h-40,'#785a3c');rr(x-9,y+17,w+18,34,'#784f43');rr(x-5,y+10,w+10,32,'#ab6852');rr(x+3,y+4,w-6,30,'#bc795b');for(let j=11;j<43;j+=8)for(let i=-2;i<w;i+=18)rr(x+i+(j%2)*5,y+j,13,2,'#d49165');rr(x-10,y+44,w+20,5,'#634e3e');rr(x+w-39,y-10,16,33,'#8d7970');rr(x+w-42,y-12,22,6,'#b39c87');const doorX=(o.label.startsWith('Mara')?6:26)*T;rr(doorX,y+h-40,32,40,'#4b4936');rr(doorX+4,y+h-36,24,36,'#785b3d');rr(doorX+5,y+h-35,2,32,'#b59058');rr(doorX+23,y+h-18,3,3,'#efd486');for(const wx of [x+24,x+w-51]){rr(wx,y+64,26,32,'#785a3b');rr(wx+3,y+67,20,25,'#aadad0');rr(wx+11,y+66,3,27,'#efe0ad');rr(wx+2,y+78,22,3,'#efe0ad');rr(wx-3,y+97,32,5,'#e4c780');}text(o.label,x+w/2,y+h+14,'#fff1b7',10);}
function object(o){const x=o.x,y=o.y,cooling=(state.cooldowns[o.id]||0)>Date.now();switch(o.type){case 'house':house(o);break;case 'tree':tree(x,y,map.id==='grove');break;case 'berries':rr(x-11,y-10,23,15,'#386e38');rr(x-8,y-15,17,18,'#629c4a');if(!cooling)for(let i=0;i<5;i++)rr(x-8+(i*7)%18,y-10+(i%2)*7,4,4,'#d97786');break;case 'log':rr(x-15,y-8,31,14,'#896340');rr(x-13,y-10,7,17,'#c8a572');rr(x-10,y-6,2,9,'#916739');rr(x-3,y-6,18,2,'#634d33');break;case 'crystals':rr(x-9,y-11,9,17,cooling?'#667a78':'#9ca7e6');rr(x+1,y-19,7,25,cooling?'#788981':'#c8c0f1');rr(x+9,y-8,5,14,'#8794c6');rr(x+2,y-16,2,15,'#e5d8f9');break;case 'sign':rr(x-2,y-12,4,18,'#806240');rr(x-15,y-27,30,18,'#b99a5a');rr(x-12,y-24,24,2,'#dac37c');rr(x-10,y-18,19,2,'#6e653e');break;case 'chest':rr(x-13,y-15,27,22,'#78522e');rr(x-12,y-20,25,12,'#c7934c');rr(x-13,y-9,27,3,'#e0bf65');rr(x-3,y-10,6,7,'#f1d777');rr(x-8,y-19,2,22,'#aa7940');break;case 'fish':rr(x-12,y-3,25,7,'#b49c62');rr(x-8,y-18,3,19,'#94734b');rr(x-7,y-18,20,2,'#cbd4b0');text('≈',x+8,y-7,'#a0e1d1',18);break;case 'shelf':rr(x-15,y-29,31,34,'#876944');rr(x-14,y-26,28,3,'#c59e65');for(let i=0;i<5;i++)rr(x-12+i*5,y-22,4,15,['#d2a56f','#769785','#a8776d'][i%3]);rr(x-14,y-6,28,4,'#c59e65');break;case 'bed':rr(x-14,y-32,28,40,'#79583e');rr(x-12,y-28,24,34,'#d9cd9d');rr(x-10,y-26,20,10,'#f6eac6');rr(x-12,y-14,24,19,'#8c9b78');break;case 'table':case 'workbench':rr(x-19,y-18,38,26,'#8e633e');rr(x-21,y-22,42,17,'#c39a60');rr(x-15,y+4,5,10,'#73513b');rr(x+11,y+4,5,10,'#73513b');if(o.type==='workbench'){rr(x-8,y-28,4,15,'#667880');rr(x-13,y-29,17,6,'#b2b8a3');}else{rr(x-5,y-26,10,8,'#ebddbb');}break;case 'plant':rr(x-7,y-8,14,15,'#bc8960');rr(x-10,y-21,20,15,'#598044');rr(x-5,y-30,10,20,'#7ca05c');break;case 'journal':rr(x-12,y-12,24,18,'#896746');rr(x-10,y-15,20,17,'#e8d9aa');rr(x,y-15,2,17,'#a79462');break;}}
function ground(x,y,t){const grove=map.id==='grove',hash=(x*73+y*127)%23;let px=x*T,py=y*T;const palette={grass:grove?'#547f60':'#6e994f',tree:grove?'#446e54':'#4b773e',path:'#c8b47d',water:'#5ca6ad',soil:'#997448',tall:'#62974c',floor:'#b49064',wall:'#645742',rug:'#a77564',building:'#987a4d'};rr(px,py,T,T,palette[t]);if(['grass','tall','tree'].includes(t)){rr(px+hash,py+8,2,3,grove?'#65936c':'#8bb76a');rr(px+5,py+hash,3,1,'#5c924e');rr(px+22,py+19,2,3,'#6d9c50');if(hash<3&&t==='grass'){rr(px+14,py+16,3,3,'#e5dbaa');rr(px+15,py+19,1,3,'#477742');}if(t==='tall')for(let i=0;i<4;i++){rr(px+3+i*8,py+5+(i%2)*12,2,10,'#467c3e');rr(px+1+i*8,py+6+(i%2)*12,6,2,'#83b65c');}}if(t==='path'){rr(px+hash,py+9,3,2,'#ae9f70');rr(px+7,py+23,2,1,'#e0ca91');}if(t==='water'){rr(px+((clockTime*6+hash)%25),py+9,7,1,'#9bcecb');rr(px+5,py+24,10,1,'#79bcbf');}if(t==='floor'){rr(px,py+15,32,1,'#9b7954');rr(px,py+31,32,1,'#8d704d');rr(px+(y%2)*14,py,1,15,'#9a7952');rr(px+22,py+16,1,16,'#9a7952');}if(t==='wall'){rr(px,py,32,12,'#bba371');rr(px,py+12,32,3,'#d1b880');}if(t==='soil')for(let i=0;i<4;i++)rr(px+3,py+3+i*8,25,3,'#775a3b');if(t==='rug'){rr(px,py,32,1,'#c69a7b');rr(px+12,py+12,7,7,'#d1b082');}}
function draw(){ctx.clearRect(0,0,W,H);camera.x=Math.max(0,Math.min(map.w*T-W,player.x-W/2));camera.y=Math.max(0,Math.min(map.h*T-H,player.y-H/2));if(map.w*T<W)camera.x=(map.w*T-W)/2;if(map.h*T<H)camera.y=(map.h*T-H)/2;ctx.save();ctx.translate(-Math.floor(camera.x),-Math.floor(camera.y));for(let y=Math.max(0,Math.floor(camera.y/T));y<Math.min(map.h,Math.ceil((camera.y+H)/T));y++)for(let x=Math.max(0,Math.floor(camera.x/T));x<Math.min(map.w,Math.ceil((camera.x+W)/T));x++)ground(x,y,map.tiles[y][x]);for(const p of map.portals){rr(p.x,p.y,p.w,p.h,map.inside?'#dbbd79':'#dbc68c');text(map.inside?'↓':p.to==='grove'?'↑':p.to==='meadow'?'→':p.to==='valley'?'←':'↑',p.x+p.w/2,p.y+p.h/2+4,'#5b6941',15);}
const entities=map.objects.map(o=>({y:o.type==='house'?o.y+o.h*T:o.y,draw:()=>object(o)}));for(const n of map.npcs){if(n.kind==='creature'&&state.team.includes(n.name))continue;entities.push({y:n.y,draw:()=>{n.kind==='human'?human(n.x,n.y,true):creature(n.x,n.y,n.name,clockTime*3);if(near===n)text(n.name,n.x,n.y-38,'#fff2bb',9);}});}entities.push({y:follower.y,draw:()=>creature(follower.x,follower.y,'Pip',player.walk)});entities.push({y:player.y,draw:()=>human(player.x,player.y,false,player.dir,player.walk)});for(let y=Math.max(0,Math.floor(camera.y/T)-2);y<Math.min(map.h,Math.ceil((camera.y+H)/T)+3);y++)for(let x=Math.max(0,Math.floor(camera.x/T)-2);x<Math.min(map.w,Math.ceil((camera.x+W)/T)+2);x++)if(map.tiles[y][x]==='tree'&&(x+y)%2===0)entities.push({y:y*T+25,draw:()=>tree(x*T+16,y*T+25,map.id==='grove')});entities.sort((a,b)=>a.y-b.y).forEach(e=>e.draw());ctx.restore();if(map.id==='grove'){ctx.fillStyle='#163b492b';ctx.fillRect(0,0,W,H);for(let i=0;i<12;i++){const x=((i*87+Math.sin(clockTime+i)*10)-camera.x*.2)%W,y=((i*73+Math.cos(clockTime+i)*8)-camera.y*.2)%H;rr(x,y,2,2,'#e3df9a');}}drawMini();}
function drawMini(){mini.clearRect(0,0,108,84);let sx=108/map.w,sy=84/map.h;for(let y=0;y<map.h;y++)for(let x=0;x<map.w;x++){mini.fillStyle={path:'#cbb788',building:'#956c49',water:'#75b9c3',wall:'#907657',floor:'#b3946c'}[map.tiles[y][x]]||'#5b804e';mini.fillRect(x*sx,y*sy,sx+1,sy+1);}mini.fillStyle='#f2dc7f';for(const p of map.portals)mini.fillRect(p.x/T*sx,p.y/T*sy,4,4);mini.fillStyle='#fff7d0';mini.fillRect(player.x/T*sx-2,player.y/T*sy-2,4,4);}
function questText(){if(!state.met)return map.id==='cottage'?'Walk up to Mara, then press Talk':'Visit Mara inside the cottage ↑';if(!state.caught)return 'Find a wild friend in the eastern meadow →';if(state.quest===0)return 'Return to Mara for your reward';if(state.quest===1)return state.upgrade<2?'Upgrade your homestead at the workbench':'Return to Mara for your reward';if(state.quest===2)return state.team.length<4?'Meet all 4 companions across the valley':state.crystals<5?'Gather 5 moon crystals in the grove':'Return to Mara for your reward';return 'A home among friends. Keep exploring!';}
function hud(){document.getElementById('place').textContent=map.name;document.getElementById('coins').textContent='◈ '+state.coins;document.getElementById('day').textContent=1+Math.floor(state.xp/80);document.getElementById('quest').textContent=questText();}
function toast(t){document.querySelector('.toast')?.remove();const d=document.createElement('div');d.className='toast';d.role='status';d.textContent=t;app.append(d);clearTimeout(toastTimer);toastTimer=setTimeout(()=>d.remove(),4200);}
function show(title,body,kicker='Mosswild'){resetInput();dialog=true;document.querySelector('.overlay')?.remove();const d=document.createElement('div');d.className='overlay';d.innerHTML=`<section class="dialog" role="dialog" aria-modal="true" aria-label="${title}"><button class="close" data-ui="close" aria-label="Close">×</button><div class="kicker">${kicker}</div><h2>${title}</h2>${body}</section>`;app.append(d);d.querySelector('button').focus();}
function close(){dialog=false;document.querySelector('.overlay')?.remove();resetInput();canvas.focus();save();hud();}
function resetInput(){keys={};stick={x:0,y:0};sprint=false;document.getElementById('knob').style.transform='';}
function changeArea(p){if(transitioning)return;transitioning=true;resetInput();document.getElementById('fade').classList.add('on');setTimeout(()=>{map=worlds[p.to];player.x=p.tx;player.y=p.ty;follower={x:p.tx-12,y:p.ty+18};near=null;hud();document.getElementById('area-title').textContent=map.name;document.getElementById('area-title').classList.add('on');document.getElementById('fade').classList.remove('on');save();setTimeout(()=>{transitioning=false},200);setTimeout(()=>document.getElementById('area-title').classList.remove('on'),1700)},180);}
function nearest(){let list=[...map.npcs.filter(n=>n.kind==='human'||!state.team.includes(n.name)),...map.objects.filter(o=>['berries','log','crystals','sign','chest','fish','workbench','journal','bed'].includes(o.type))];let best=null,dist=43;for(const o of list){let d=Math.hypot(o.x-player.x,o.y-player.y);if(d<dist){best=o;dist=d;}}return best;}
function interact(){if(dialog||transitioning)return;near=nearest();if(!near){toast('Walk closer to interact.');return;}const o=near;if(o.kind==='human'){state.met=true;let reward=state.quest===0&&state.caught?60:state.quest===1&&state.upgrade>1?120:state.quest===2&&state.team.length>=4&&state.crystals>=5?200:0;if(reward){state.coins+=reward;state.xp+=40;state.quest++;toast(`Chapter complete! +${reward} coins · +40 XP`);}show('Mara',`<p>“${reward?'Look at how far you and your friends have come. Here’s a little something for your next adventure.':!state.caught?'Welcome to Willowmere! Take the eastern path to the meadow. Walk up to a creature, give it a little attention, and offer a berry when it trusts you.':'Your companions gather supplies even while you’re away. Visit your homestead to collect them and improve your camp.'}”</p><p><b>Next:</b> ${questText()}</p><div class="actions"><button data-ui="close">Back to exploring</button></div>`,'Valley keeper');}else if(o.kind==='creature'){encounter={name:o.name,trust:0};encounterDialog();}else if(o.type==='sign'){show('Trail sign',`<p>${o.text.replace(/\n/g,'<br>')}</p><div class="actions"><button data-ui="close">Keep walking</button></div>`);}else if(o.type==='chest'||o.type==='journal'){bag();}else if(o.type==='workbench'){upgradeDialog();}else if(o.type==='bed'){show('A little rest',`<p>Your companions keep gathering while you’re away. Your progress is saved automatically on this device.</p><div class="actions"><button data-ui="close">Back to exploring</button></div>`);}else{const cooldown=state.cooldowns[o.id]||0;if(cooldown>Date.now()){toast(`Ready again in ${Math.ceil((cooldown-Date.now())/1000)} seconds.`);return;}const key={berries:'berries',log:'wood',crystals:'crystals',fish:'fish'}[o.type];state[key]+=o.type==='crystals'?2:3;state.xp+=5;state.cooldowns[o.id]=Date.now()+20000;toast(`+${o.type==='crystals'?2:3} ${key} · +5 XP`);}save();hud();}
function encounterDialog(){let e=encounter;show(`Wild ${e.name}`,`<canvas id="portrait" width="48" height="48" class="portrait" aria-label="${e.name}"></canvas><p>${e.trust===0?'It pauses and looks at you. Approach gently.':e.trust===1?'It takes a curious step closer. You’re making a connection!':'It trusts you! Offer a berry to invite it home.'}</p><p>Trust: ${e.trust} / 2</p><div class="health"><div style="width:${e.trust*50}%"></div></div><div class="actions"><button data-ui="gentle" ${e.trust>=2?'disabled':''}>Play gently</button><button data-ui="befriend" ${e.trust<2||state.berries<1?'disabled':''}>Offer berry (${state.berries})</button><button data-ui="close">Leave</button></div>`,'Creature encounter');const pc=document.getElementById('portrait').getContext('2d');pc.fillStyle=colors[e.name];pc.fillRect(10,15,28,25);pc.fillRect(8,5,8,17);pc.fillRect(31,5,8,17);pc.fillStyle='#324d39';pc.fillRect(15,24,3,4);pc.fillRect(30,24,3,4);pc.fillRect(23,32,3,2);}
function bankTotal(){return Object.values(state.bank).reduce((a,b)=>a+Math.floor(b),0)}
function icon(name){return typeof gameIcon==='function'?gameIcon(name):'';}
function bag(){accrue();show('Your bag & companions',`<div class="statgrid icon-stats">${Object.keys(rates).map(k=>`<div>${icon(k)}<b>${state[k]}</b>${k}</div>`).join('')}</div><p class="coin-line">${icon('coins')}${state.coins} coins · Camp level ${state.upgrade}</p>${state.team.map(n=>`<div class="row card"><div class="card-icon">${icon(state.jobs[n])}</div><div><b>${n}</b><small>${Math.round(3600/rates[state.jobs[n]]*state.upgrade)} supplies / hour</small></div><select aria-label="Task for ${n}" data-job="${n}">${Object.keys(rates).map(k=>`<option value="${k}" ${state.jobs[n]===k?'selected':''}>${names[k]}</option>`).join('')}</select></div>`).join('')}<p class="coin-line"><b>${bankTotal()} supplies</b> ready to collect. Friends keep working for up to 8 hours away.</p><div class="actions"><button data-ui="collect">${icon('bag')}Collect supplies</button><button data-ui="close">${icon('boot')}Back to the world</button></div>`,'Progress saves on this device');}
function upgradeDialog(){const wood=state.upgrade*10,coins=state.upgrade*50;show('Improve your homestead',`<p>Camp level ${state.upgrade}. The next level adds another base gathering rate for every companion.</p><p>Cost: ${wood} wood + ${coins} coins.<br>You have ${state.wood} wood + ${state.coins} coins.</p><div class="actions"><button data-ui="upgrade" ${state.wood<wood||state.coins<coins?'disabled':''}>Build upgrade</button><button data-ui="close">Leave workbench</button></div>`,'Workbench');}
function help(){show('Make yourself at home',`<p><b>Move:</b> drag the joystick, use WASD / arrow keys, or a connected controller’s left stick / D-pad.</p><p><b>Interact:</b> walk close, then press E / Space, controller A, or the round action button. Walk through doorways and along paths to enter other areas.</p><p><b>Run:</b> hold Shift, controller B, or Run. Open your bag with I or the top-right button.</p><p>Mara’s cottage is just north of where you begin. The meadow is east; the grove is north. Your homestead is northeast of the village crossroads.</p><div class="actions"><button data-ui="close">Let’s explore</button></div>`,'Controls');}
app.addEventListener('click',e=>{const b=e.target.closest('[data-ui]');if(!b||b.disabled)return;switch(b.dataset.ui){case 'close':close();break;case 'help':help();break;case 'bag':bag();break;case 'gentle':if(encounter){encounter.trust=Math.min(2,encounter.trust+1);encounterDialog();}break;case 'befriend':if(encounter&&encounter.trust>=2&&state.berries>0&&!state.team.includes(encounter.name)){state.berries--;state.team.push(encounter.name);state.jobs[encounter.name]=encounter.name==='Emberkin'?'wood':encounter.name==='Dewdrop'?'fish':'crystals';state.caught=true;state.xp+=30;const name=encounter.name;encounter=null;close();toast(`${name} joined your camp! +30 XP`);}break;case 'collect':accrue();let total=0;for(const k of Object.keys(rates)){let n=Math.floor(state.bank[k]||0);state[k]+=n;state.bank[k]-=n;total+=n;}bag();toast(total?`Collected ${total} supplies!`:'Your companions are still gathering.');break;case 'upgrade':if(state.wood>=state.upgrade*10&&state.coins>=state.upgrade*50){state.wood-=state.upgrade*10;state.coins-=state.upgrade*50;accrue();state.upgrade++;close();toast('Homestead upgraded! Companions gather faster.');}break;}save();hud();});
app.addEventListener('change',e=>{if(e.target.dataset.job&&rates[e.target.value]){accrue();state.jobs[e.target.dataset.job]=e.target.value;save();bag();}});
function keyHandler(e,down){if(['SELECT','INPUT'].includes(e.target.tagName))return;const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' ','w','a','s','d'].includes(k))e.preventDefault();if(down&&!e.repeat){if(k==='escape'){if(dialog)close();return;}if(k==='i'){dialog?close():bag();return;}if((k==='e'||k===' ')&&!dialog)interact();}if(!dialog)keys[k]=down;if(dialog&&k==='tab'){const els=[...document.querySelectorAll('.dialog button:not(:disabled),.dialog select,.dialog input')];if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0].focus();}}}
addEventListener('keydown',e=>keyHandler(e,true));addEventListener('keyup',e=>keyHandler(e,false));addEventListener('blur',resetInput);document.addEventListener('visibilitychange',()=>{resetInput();accrue();save();});addEventListener('pagehide',save);
const joy=document.getElementById('joystick');let pointer=null;
function joyMove(e){if(pointer!==e.pointerId)return;const b=joy.getBoundingClientRect(),dx=e.clientX-b.left-b.width/2,dy=e.clientY-b.top-b.height/2,max=b.width*.32,len=Math.hypot(dx,dy),scale=len>max?max/len:1;stick={x:dx*scale/max,y:dy*scale/max};document.getElementById('knob').style.transform=`translate(${dx*scale}px,${dy*scale}px)`;}
joy.addEventListener('pointerdown',e=>{if(dialog)return;pointer=e.pointerId;joy.setPointerCapture(pointer);joyMove(e);});joy.addEventListener('pointermove',joyMove);for(const ev of ['pointerup','pointercancel','lostpointercapture'])joy.addEventListener(ev,()=>{pointer=null;stick={x:0,y:0};document.getElementById('knob').style.transform='';});
document.getElementById('action').addEventListener('click',()=>interact());const run=document.getElementById('run');run.addEventListener('click',()=>{if(typeof runLatched==='undefined')return;runLatched=!runLatched;run.setAttribute('aria-pressed',String(runLatched));run.textContent=runLatched?'Walk':'Run';});
let prev=performance.now();function frame(now){const dt=Math.min((now-prev)/1000,.04);prev=now;clockTime+=dt;if(typeof tickActivities==='function')tickActivities(dt);let gx=0,gy=0,grun=false;const pad=[...(navigator.getGamepads?.()||[])].find(p=>p?.connected);if(pad){document.getElementById('pad').textContent='Controller connected';gx=Math.abs(pad.axes[0]||0)>.18?pad.axes[0]:0;gy=Math.abs(pad.axes[1]||0)>.18?pad.axes[1]:0;if(pad.buttons[14]?.pressed)gx=-1;if(pad.buttons[15]?.pressed)gx=1;if(pad.buttons[12]?.pressed)gy=-1;if(pad.buttons[13]?.pressed)gy=1;grun=pad.buttons[1]?.pressed;if(dialog){const direction=(pad.buttons[13]?.pressed||pad.buttons[15]?.pressed?1:0)-(pad.buttons[12]?.pressed||pad.buttons[14]?.pressed?1:0);if(direction&&direction!==padNav){const buttons=[...document.querySelectorAll('.dialog button:not(:disabled),.dialog select')],index=buttons.indexOf(document.activeElement);buttons[(index+direction+buttons.length)%buttons.length]?.focus();}padNav=direction;if(grun&&!padBack)close();}else padNav=0;padBack=grun;const press=pad.buttons[0]?.pressed;if(press&&!padPressed){if(dialog){const focused=document.activeElement;if(focused?.matches('.dialog button'))focused.click();}else interact();}padPressed=press;}else{document.getElementById('pad').textContent='';padPressed=false;}
if(!dialog&&!transitioning&&(typeof SaveStore==='undefined'||!SaveStore.status().blocked)){let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+stick.x+gx,dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+stick.y+gy,len=Math.hypot(dx,dy);if(len>.08){dx/=Math.max(1,len);dy/=Math.max(1,len);const speed=(sprint||keys.shift||grun||(typeof runLatched!=='undefined'&&runLatched))?140:88;move(map,player,dx*speed*dt,dy*speed*dt);player.walk+=dt*12;player.dir=Math.abs(dx)>Math.abs(dy)?(dx<0?1:2):(dy<0?3:0);}else player.walk=0;const fd=Math.hypot(player.x-follower.x,player.y-follower.y);if(fd>24){follower.x+=(player.x-follower.x)*Math.min(1,dt*5);follower.y+=(player.y-follower.y)*Math.min(1,dt*5);}const p=portalAt(map,player);if(p)changeArea(p);for(const n of map.npcs)if(n.kind==='creature'&&!state.team.includes(n.name)){const tx=n.homeX+Math.sin(clockTime*.3+n.seed)*30,ty=n.homeY+Math.cos(clockTime*.25+n.seed)*20;move(map,n,(tx-n.x)*dt*.7,(ty-n.y)*dt*.7);}near=nearest();const labels={berries:'Pick berries',log:'Gather wood',crystals:'Mine crystals',fish:'Catch fish',sign:'Read sign',chest:'Open supplies',workbench:'Upgrade camp',journal:'Open journal',bed:'Rest'};document.getElementById('near').textContent=near?(near.name||labels[near.type]):'Walk up to a person or object';document.getElementById('action').disabled=!near;if(typeof gameIcon==='undefined')document.getElementById('action').innerHTML=(near?(near.kind==='human'?'Talk':near.kind==='creature'?'Meet':'Use'):'Action')+'<small>E / A</small>';}
draw();if(typeof drawActivities==='function'){drawActivities();interactionHUD();}requestAnimationFrame(frame);}
hud();requestAnimationFrame(frame);setInterval(()=>{accrue();save();hud()},2000);if(away>60000&&bankTotal()>0)toast(`Welcome back! ${bankTotal()} supplies are waiting in your bag.`);else toast(state.met?'Adventure continued. Open Journal for your next chapter.':'Walk north into Mara’s cottage. Drag the joystick or use WASD.');
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_valley_progress',description:'Read area, player position, nearby interaction, inventory and companions.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||Object.keys(input).length)throw new Error('Expected an empty object');return {area:map.id,player:{x:player.x,y:player.y,facing:['south','west','east','north'][player.dir]},activity:typeof activity==='undefined'||!activity?null:{type:activity.o.type,elapsed:activity.elapsed},nearby:near?.name||near?.type||null,companions:state.team,inventory:{berries:state.berries,wood:state.wood,fish:state.fish,crystals:state.crystals},chapter:state.quest+1,exploration:state.exploration||{},audio:typeof GameAudio==='undefined'?null:GameAudio.status};}})).catch(()=>{});}catch{}}
if(typeof Image!=='undefined')setTimeout(()=>{
// The central valley uses the supplied settlement scene and four-direction traveller frames.
const ValleyVisuals=(()=>{const mapArt=new Image(),foreground=new Image(),directions={},friends={};let ready=false,foregroundReady=false;mapArt.onload=()=>ready=true;mapArt.src='assets/settlement/Pellet Town.png';foreground.onload=()=>foregroundReady=true;foreground.src='assets/settlement/foregroundObjects.png';for(const [name,file] of Object.entries({0:'playerUp.png',1:'playerLeft.png',2:'playerRight.png',3:'playerDown.png'})){const image=new Image();image.src='assets/settlement/'+file;directions[name]=image;}for(const [name,file] of Object.entries({Pip:'draggleSprite.png',Emberkin:'embySprite.png'})){const image=new Image();image.src='assets/settlement/'+file;friends[name]=image;}const crop={x:720,y:255,w:2110,h:1640};function background(g,x,y,w,h){if(!ready)return false;g.imageSmoothingEnabled=false;g.drawImage(mapArt,crop.x+crop.w*x/w,crop.y+crop.h*y/h,crop.w*32/w,crop.h*32/h,x,y,32,32);return true;}function canopy(g,w,h){if(!foregroundReady)return;g.save();g.imageSmoothingEnabled=false;g.drawImage(foreground,crop.x,crop.y,crop.w,crop.h,0,0,w,h);g.restore();}function traveller(g,x,y,dir,walk,height=38){const image=directions[dir];if(!image?.complete||!image.naturalWidth)return false;const frame=Math.floor((walk||0)*7)%4,sw=image.naturalWidth/4,width=Math.round(height*(sw/image.naturalHeight));g.save();g.imageSmoothingEnabled=false;g.drawImage(image,frame*sw,0,sw,image.naturalHeight,Math.round(x-width/2),Math.round(y-height),width,height);g.restore();return true;}function friend(g,name,x,y,walk,height=23){const image=friends[name];if(!image?.complete||!image.naturalWidth)return false;const frame=Math.floor((walk||0)*6)%4,sw=image.naturalWidth/4,width=Math.round(height*(sw/image.naturalHeight));g.save();g.imageSmoothingEnabled=false;g.drawImage(image,frame*sw,0,sw,image.naturalHeight,Math.round(x-width/2),Math.round(y-height),width,height);g.restore();return true;}return {background,canopy,traveller,friend,get ready(){return ready;}};})();
const settlementGround=ground;ground=function(x,y,t){if(map.id==='valley'&&ValleyVisuals.background(ctx,x*T,y*T,map.w*T,map.h*T))return;settlementGround(x,y,t);};
const settlementObject=object;object=function(o){if(map.id==='valley'&&['house','tree'].includes(o.type))return;settlementObject(o);};
const settlementHuman=human;human=function(x,y,npc=false,dir=0,walk=0){if(!npc&&ValleyVisuals.traveller(ctx,x,y,dir,walk,38))return;settlementHuman(x,y,npc,dir,walk);};
const settlementCreature=creature;creature=function(x,y,name,walk=0){if(map.id==='valley'&&ValleyVisuals.friend(ctx,name,x,y,walk,23))return;settlementCreature(x,y,name,walk);};
const settlementDraw=draw;draw=function(){settlementDraw();if(map.id==='valley'&&ValleyVisuals.ready){ctx.save();ctx.translate(-Math.floor(camera.x),-Math.floor(camera.y));ValleyVisuals.canopy(ctx,map.w*T,map.h*T);ctx.restore();}};
},0);



